'use strict';
const config = window.KAT_CONFIG || {};
const $ = (selector, root = document) => root.querySelector(selector);
const $$ = (selector, root = document) => [...root.querySelectorAll(selector)];
const treatments = {
  consultation: {title:'Aesthetics consultation', eyebrow:'START WITH YOU', text:'Time to talk about what matters to you. Explore your goals and discuss suitable options with your practitioner before deciding on any treatment.', image:'treatment-one', points:['Discuss the look you have in mind','Review suitability with your practitioner','Ask about risks, alternatives, aftercare and costs'], faq:'Your practitioner will discuss the available options following an individual assessment. A consultation does not commit you to a treatment.'},
  fillers: {title:'Dermal fillers', eyebrow:'THOUGHTFUL DEFINITION', text:'A personal consultation to explore your features and discuss whether a dermal filler treatment is appropriate for your goals.', image:'treatment-two', points:['Discuss your individual treatment goals','Review suitability, risks and alternatives','Agree on a plan and understand aftercare'], faq:'Recommendations, product choice, prices and follow-up arrangements must be confirmed by the practitioner after assessment. No result is guaranteed.'},
  makeup: {title:'Semi-permanent makeup', eyebrow:'DETAILS THAT FEEL LIKE YOU', text:'Explore brow, eye and lip options, with a discussion about shape, colour and your everyday preferences.', image:'treatment-three', points:['Discuss shape and colour preferences','Review suitability and any required patch testing','Understand appointments, healing and aftercare'], faq:'The practitioner will confirm preparation, healing expectations and whether a follow-up appointment is needed. Treatment availability and pricing are to be confirmed.'}
};
const detailDialog = $('#detail-dialog');
const bookingDialog = $('#booking-dialog');
const bookingForm = $('#booking-form');
let draft = null;
let toastTimer;
const safeUrl = value => {try {const url = new URL(value); return url.protocol === 'https:' ? url.href : null;}catch{return null;}};
function toast(text){$('#toast').textContent=text;$('#toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').hidden=true,4500);}
function showDialog(dialog){if(dialog.open)return;dialog.showModal();}
function closeMenu(){const toggle=$('.menu-toggle');toggle.setAttribute('aria-expanded','false');toggle.setAttribute('aria-label','Open menu');$('#navigation').classList.remove('open');}
$('.menu-toggle').addEventListener('click',()=>{const open=$('.menu-toggle').getAttribute('aria-expanded')!=='true';$('.menu-toggle').setAttribute('aria-expanded',String(open));$('.menu-toggle').setAttribute('aria-label',open?'Close menu':'Open menu');$('#navigation').classList.toggle('open',open);});
$$('#navigation a').forEach(a=>a.addEventListener('click',()=>{closeMenu();$$('#navigation a').forEach(link=>link.classList.toggle('active',link===a));}));
document.addEventListener('keydown',event=>{if(event.key==='Escape')closeMenu();});
document.addEventListener('click',event=>{if(!event.target.closest('.header'))closeMenu();});
if('IntersectionObserver' in window){const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting)$$('#navigation a').forEach(a=>a.classList.toggle('active',a.hash==='#'+entry.target.id));}),{rootMargin:'-20% 0px -55% 0px'});$$('main section[id]').forEach(section=>observer.observe(section));}
$$('dialog').forEach(dialog=>{dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});$('[data-close]',dialog).addEventListener('click',()=>dialog.close());});
function showTreatment(key){const item=treatments[key];if(!item)throw new Error('Unknown treatment');$('#detail-content').innerHTML=`<p class="eyebrow">${item.eyebrow}</p><h2>${item.title}</h2><div class="photo ${item.image}"><img src="assets/kat-reference.png" alt="Reference imagery for ${item.title.toLowerCase()}"></div><p>${item.text}</p><h3>Your consultation</h3><ul>${item.points.map(p=>`<li>${p}</li>`).join('')}</ul><p class="form-note">Treatment prices, practitioner credentials and availability are placeholders pending clinic confirmation.</p><details><summary>What should I know before booking?</summary><p>${item.faq}</p></details><details><summary>Can I ask a question first?</summary><p>Of course. Use the enquiry form to prepare your questions. This preview does not send messages to the clinic.</p></details><button class="button" data-book="${key}">Plan a consultation <span>↗</span></button>`;showDialog(detailDialog);}
$$('[data-treatment]').forEach(button=>button.addEventListener('click',()=>showTreatment(button.dataset.treatment)));
const info={
 about:{title:'Meet Kat',eyebrow:'A PERSONAL APPROACH',body:'<p>Kat Aesthetics is built around a simple idea: taking time to understand the person behind every treatment.</p><p>Your consultation is a chance to share your goals, ask questions and explore your options in a calm, considered setting.</p><h3>Get to know your practitioner</h3><p class="form-note">Kat’s approved biography, qualifications, registration details and professional credentials will be added here before public launch.</p><button class="button" data-book>Plan a consultation <span>↗</span></button>'},
 privacy:{title:'Privacy information',eyebrow:'YOUR INFORMATION',body:'<p>This is a private website preview. The demonstration consultation and enquiry forms process details in your browser only. They do not send them to Kat Aesthetics or store them in a clinic database.</p><p>Downloading a draft saves a text file on your device. Closing or reloading the page clears the form data held by this page. No advertising or analytics scripts are included.</p><p>The hosting service may process technical access information to deliver the website. If a real email or booking provider is configured later, it will have its own data handling requirements.</p><p class="form-note">Placeholder notice: the clinic’s legal identity, contact information, retention periods and full privacy policy must be supplied before collecting real enquiries.</p>'},
 terms:{title:'Terms & conditions',eyebrow:'BEFORE YOUR VISIT',body:'<p>This website is a design preview. Prices, appointment availability, practitioner credentials, contact details and clinic policies are not yet confirmed.</p><p>Creating a consultation draft does not reserve a time, send an enquiry or enter into a treatment agreement. No payment is taken.</p><p>Reference imagery is illustrative and is not evidence of client outcomes. The sample testimonials require verification. Treatment suitability and outcomes are individual and must be discussed with the practitioner.</p><p class="form-note">The clinic’s final booking, cancellation, deposit, complaints and treatment terms will be published here before launch.</p>'},
 instagram:{title:'Follow Kat on Instagram',eyebrow:'LET’S CONNECT',body:'<p>The official Instagram profile will be linked here as soon as the clinic’s account is confirmed.</p><p class="form-note">Social profile placeholder.</p>'},
 facebook:{title:'Find Kat on Facebook',eyebrow:'LET’S CONNECT',body:'<p>The official Facebook page will be linked here as soon as the clinic’s account is confirmed.</p><p class="form-note">Social profile placeholder.</p>'}
};
document.addEventListener('click',event=>{const book=event.target.closest('[data-book]');if(book){openBooking(book.dataset.book||'consultation');return;}const button=event.target.closest('[data-info]');if(!button)return;const key=button.dataset.info;const external=(key==='instagram'||key==='facebook')&&safeUrl(config[key+'Url']);if(external){window.open(external,'_blank','noopener,noreferrer');return;}const content=info[key];if(!content)return;$('#detail-content').innerHTML=`<p class="eyebrow">${content.eyebrow}</p><h2>${content.title}</h2>${content.body}`;showDialog(detailDialog);});
$$('[data-filter]').forEach(button=>button.addEventListener('click',()=>{$$('[data-filter]').forEach(item=>{const active=item===button;item.classList.toggle('active',active);item.setAttribute('aria-pressed',String(active));});$$('[data-gallery]').forEach(item=>item.hidden=button.dataset.filter!=='all'&&item.dataset.gallery!==button.dataset.filter);}));
$$('[data-gallery]').forEach(button=>button.addEventListener('click',()=>{const item=treatments[button.dataset.gallery];$('#detail-content').innerHTML=`<p class="eyebrow">THE FINER DETAILS</p><h2>${item.title}</h2><div class="photo ${item.image}"><img src="assets/kat-reference.png" alt="Illustrative ${item.title.toLowerCase()} image"></div><p>Inspiration from the supplied design. This is not a before-and-after result or a verified client photograph.</p><p class="form-note">A consented client gallery will replace this placeholder.</p><button class="button" data-book="${button.dataset.gallery}">Plan a consultation <span>↗</span></button>`;showDialog(detailDialog);}));
const reviews=[{quote:'Kat is amazing! She makes you feel so at ease and really listens. My results are so natural — I wouldn’t trust anyone else!',name:'Sophie M.'},{quote:'Professional, knowledgeable and such a lovely person. My lips have never looked better. Thank you Kat!',name:'Laura T.'},{quote:'The best in the business! My brows are perfect and have saved me so much time every day. Highly recommend!',name:'Chloe R.'}];let reviewIndex=0;
function renderReview(){const item=reviews[reviewIndex];$('#review-quote').textContent=item.quote;$('#review-name').textContent=item.name;$('#review-position').textContent=`0${reviewIndex+1} / 03`;}
$('#review-prev').addEventListener('click',()=>{reviewIndex=(reviewIndex+reviews.length-1)%reviews.length;renderReview();});$('#review-next').addEventListener('click',()=>{reviewIndex=(reviewIndex+1)%reviews.length;renderReview();});renderReview();
function localDate(date){return `${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`;}
function setMinDate(){const tomorrow=new Date();tomorrow.setDate(tomorrow.getDate()+1);$('#booking-date').min=localDate(tomorrow);}
function setStep(step){['one','two','three'].forEach((word,index)=>{$('#booking-step-'+word).hidden=index+1!==step;});$$('.steps li').forEach((li,index)=>{li.classList.toggle('current',index+1===step);if(index+1===step)li.setAttribute('aria-current','step');else li.removeAttribute('aria-current');});$$('#booking-step-two input').forEach(input=>input.disabled=step!==2);$('#booking-next').disabled=step!==1;if(step===2)$('#booking-step-two input').focus();if(step===3)$('#download-booking').focus();}
function openBooking(key='consultation'){if(!treatments[key])throw new Error('Unknown treatment');const external=safeUrl(config.bookingUrl);if(external){window.open(external,'_blank','noopener,noreferrer');return;}detailDialog.close();closeMenu();bookingForm.reset();draft=null;setMinDate();$(`input[name="service"][value="${key}"]`).checked=true;setStep(1);showDialog(bookingDialog);}
function selectionSummary(data){const date=new Date(data.date+'T12:00:00');return `${treatments[data.service].title}\n${date.toLocaleDateString('en-GB',{weekday:'long',day:'numeric',month:'long',year:'numeric'})} · ${data.time}\nPreference only — availability not confirmed.`;}
$('#booking-next').addEventListener('click',()=>{setMinDate();const valid=$$('input,select', $('#booking-step-one')).every(input=>input.reportValidity());if(!valid)return;const data=Object.fromEntries(new FormData(bookingForm));$('#booking-summary').textContent=selectionSummary(data);setStep(2);});
$('#booking-back').addEventListener('click',()=>{setStep(1);$('#booking-date').focus();});
bookingForm.addEventListener('submit',event=>{event.preventDefault();if(!$('#booking-step-two').hidden&&bookingForm.reportValidity()){const data=Object.fromEntries(new FormData(bookingForm));setMinDate();if(data.date<$('#booking-date').min){setStep(1);$('#booking-date').reportValidity();return;}if(!data.name.trim()){bookingForm.elements.name.setCustomValidity('Please enter your name.');bookingForm.elements.name.reportValidity();return;}draft={...data,name:data.name.trim()};$('#booking-confirmation').textContent=`${draft.name}\n${draft.email}\n\n${selectionSummary(draft)}`;setStep(3);}});
bookingForm.elements.name.addEventListener('input',()=>bookingForm.elements.name.setCustomValidity(''));
function download(filename,content){const url=URL.createObjectURL(new Blob([content],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=filename;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Your draft download has started.');}
$('#download-booking').addEventListener('click',()=>{if(!draft)return;download('kat-consultation-draft.txt',`KAT AESTHETICS — CONSULTATION DRAFT\n\nDEMO ONLY. No appointment is booked and this has not been sent.\n\n${selectionSummary(draft)}\n\nName: ${draft.name}\nEmail: ${draft.email}\nPhone: ${draft.phone||'Not provided'}\n\nContact the clinic when confirmed contact details become available.`);});
$('#booking-restart').addEventListener('click',()=>openBooking());
bookingDialog.addEventListener('close',()=>{draft=null;bookingForm.reset();});
$('#contact-form').addEventListener('submit',event=>{event.preventDefault();const form=event.currentTarget;if(!form.reportValidity())return;const data=Object.fromEntries(new FormData(form));if(!data.name.trim()||data.message.trim().length<10){$('#contact-status').textContent='Please add your name and a message of at least 10 characters.';return;}const body=`Name: ${data.name.trim()}\nEmail: ${data.email}\nInterested in: ${data.treatment}\n\n${data.message.trim()}`;if(config.email&&/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(config.email)){window.location.href=`mailto:${encodeURIComponent(config.email)}?subject=${encodeURIComponent('Kat Aesthetics enquiry')}&body=${encodeURIComponent(body)}`;$('#contact-status').textContent='Your email app has been opened. Send the message there to contact the clinic.';}else{download('kat-enquiry-draft.txt',`KAT AESTHETICS — ENQUIRY DRAFT\n\nDEMO ONLY. This enquiry has not been sent.\n\n${body}`);$('#contact-status').textContent='Your draft is ready to download. Nothing has been sent to the clinic.';}});
if(config.address)$('#contact-location').textContent=config.address;
if(config.email&&/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(config.email)){const link=document.createElement('a');link.href='mailto:'+config.email;link.textContent=config.email;$('#contact-address').replaceChildren(link);$('#contact-mode').textContent='This opens your email app. Your message is sent only when you send it there.';$('#contact-submit').firstChild.textContent='Open enquiry in email ';}
if(config.phone){const link=document.createElement('a');link.href='tel:'+config.phone.replace(/[^+\d]/g,'');link.textContent=config.phone;$('#contact-address').append(document.createElement('br'),link);}
$('#year').textContent=new Date().getFullYear();setMinDate();setStep(1);
const context=document.modelContext;if(context?.registerTool){const lifecycle=new AbortController();try{Promise.resolve(context.registerTool({name:'start_consultation_draft',title:'Start consultation draft',description:'Open the demonstration consultation form for a chosen treatment. Does not book or send anything.',inputSchema:{type:'object',properties:{treatment:{type:'string',enum:Object.keys(treatments)}},required:['treatment'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||typeof input!=='object'||Object.keys(input).some(key=>key!=='treatment')||!Object.hasOwn(treatments,input.treatment))throw new Error('Choose a listed treatment.');if(safeUrl(config.bookingUrl))return{status:'external_booking_available',url:safeUrl(config.bookingUrl)};openBooking(input.treatment);return{status:'draft_form_open',treatment:input.treatment,booked:false};}},{signal:lifecycle.signal})).catch(()=>{});}catch{}window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}
